'use client';

/**
 * Sign in — email and password with a show/hide toggle, "keep me signed in", a passkey option and legal links.
 * A centred card on narrow containers; from 960px of its own width it becomes two columns with a brand panel
 * in the tenant's primary action colours. Built only from Strata components; copy comes from `content`.
 *
 * `headingLevel` (default 1) is the level of the sign-in title. Above 1 the block is embedded in another page and
 * renders no <main> or <footer> landmarks.
 */

import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardFooter, CardHeader, CardTitle } from '@/components/ui/card';
import { Checkbox } from '@/components/ui/checkbox';
import { Link } from '@/components/ui/link';
import { Separator } from '@/components/ui/separator';
import { TextField } from '@/components/ui/text-field';
import { ToastRegion, toast } from '@/components/ui/toast';
import { IconEye, IconEyeOff, IconKey } from '@tabler/icons-react';
import { useId, useRef, useState, type FormEvent, type JSX, type MouseEvent } from 'react';
import { signInContent, type SignInContent } from './sign-in.content';
import styles from './sign-in.module.css';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

type Level = 1 | 2 | 3 | 4 | 5 | 6;
const level = (n: number): Level => Math.min(6, Math.max(1, Math.round(n))) as Level;

/** Demo links point at "#": keep them from navigating (or scrolling a host page to the top). */
const stay = (e: MouseEvent<Element>) => e.preventDefault();

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export interface SignInProps {
  /** All copy. Defaults to the English sample in ./sign-in.content.ts. */
  content?: SignInContent;
  /** Level of the sign-in title (default 1). Above 1 the block renders as embedded: no <main> or <footer> landmarks. */
  headingLevel?: 1 | 2 | 3 | 4;
  className?: string;
}

export function SignIn({ content = signInContent, headingLevel = 1, className }: SignInProps): JSX.Element {
  const uid = useId();
  const c = content.signIn;
  const embedded = headingLevel > 1;
  const Main = embedded ? 'div' : 'main';
  const Footer = embedded ? 'div' : 'footer';
  const monogram = Array.from(content.product.name.trim())[0] ?? '';

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [visible, setVisible] = useState(false);
  const [errors, setErrors] = useState<{ email?: string; password?: string }>({});
  const [pending, setPending] = useState(false);
  const emailRef = useRef<HTMLInputElement>(null);
  const passwordRef = useRef<HTMLInputElement>(null);

  const validate = (next: { email: string; password: string }) => ({
    email: !next.email.trim() ? c.email.errors.required : EMAIL.test(next.email.trim()) ? undefined : c.email.errors.invalid,
    password: next.password ? undefined : c.password.errors.required,
  });

  const onSubmit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const found = validate({ email, password });
    setErrors(found);
    if (found.email) return emailRef.current?.focus();
    if (found.password) return passwordRef.current?.focus();
    setPending(true);
    // Stands in for the network request.
    setTimeout(() => {
      setPending(false);
      toast({ title: c.success.title, tone: 'success' });
    }, 1200);
  };

  return (
    <div className={cx(styles.root, className)}>
      <Main className={styles.layout} aria-labelledby={embedded ? undefined : `${uid}-title`}>
        <div className={styles.formSide}>
          <Card className={styles.card}>
            <CardHeader className={styles.cardHeader}>
              <span className={styles.logoMark} aria-hidden="true">
                {monogram}
              </span>
              <CardTitle level={level(headingLevel)} id={`${uid}-title`} className={styles.title}>
                {c.title}
              </CardTitle>
              <CardDescription>{c.subtitle}</CardDescription>
            </CardHeader>

            <form noValidate onSubmit={onSubmit} aria-labelledby={`${uid}-title`} className={styles.form}>
              <CardContent className={styles.fields}>
                <TextField
                  inputRef={emailRef}
                  label={c.email.label}
                  placeholder={c.email.placeholder}
                  type="email"
                  name="email"
                  autoComplete="username"
                  value={email}
                  onChange={(v) => {
                    setEmail(v);
                    if (errors.email) setErrors((x) => ({ ...x, email: validate({ email: v, password }).email }));
                  }}
                  isRequired
                  validationBehavior="aria"
                  isInvalid={!!errors.email}
                  errorMessage={errors.email}
                  className={styles.ltrValue}
                />
                <TextField
                  inputRef={passwordRef}
                  label={c.password.label}
                  type={visible ? 'text' : 'password'}
                  name="password"
                  autoComplete="current-password"
                  value={password}
                  onChange={(v) => {
                    setPassword(v);
                    if (errors.password) setErrors((x) => ({ ...x, password: validate({ email, password: v }).password }));
                  }}
                  isRequired
                  validationBehavior="aria"
                  isInvalid={!!errors.password}
                  errorMessage={errors.password}
                  suffix={
                    <Button
                      variant="ghost"
                      size="icon"
                      aria-label={visible ? c.password.hide : c.password.show}
                      onPress={() => setVisible((v) => !v)}
                      className={styles.reveal}
                    >
                      {visible ? <IconEyeOff aria-hidden /> : <IconEye aria-hidden />}
                    </Button>
                  }
                />
                <div className={styles.options}>
                  <Checkbox name="remember" defaultSelected>
                    {c.remember}
                  </Checkbox>
                  <Link href="#" onClick={stay} variant="standalone" className={styles.small}>
                    {c.password.forgot}
                  </Link>
                </div>
                <Button type="submit" isPending={pending} className={styles.full}>
                  {c.submit}
                </Button>
                <Separator label={c.or} />
                <Button variant="outline" className={styles.full}>
                  <IconKey aria-hidden />
                  {c.passkey}
                </Button>
              </CardContent>
            </form>

            <CardFooter className={styles.cardFooter}>
              <span className={styles.muted}>{c.signUp.prompt}</span>
              <Link href="#" onClick={stay} variant="standalone">
                {c.signUp.action}
              </Link>
            </CardFooter>
          </Card>

          <Footer className={styles.legal}>
            <ul className={styles.legalList}>
              {[c.legal.terms, c.legal.privacy, c.legal.help].map((label) => (
                <li key={label}>
                  <Link href="#" onClick={stay} variant="standalone" className={styles.legalLink}>
                    {label}
                  </Link>
                </li>
              ))}
            </ul>
          </Footer>
        </div>

        <div className={styles.brandPanel}>
          <span className={styles.brand}>
            <span className={styles.brandMark} aria-hidden="true">
              {monogram}
            </span>
            <span className={styles.brandName}>{content.product.name}</span>
          </span>
          <div className={styles.brandCopy}>
            <p className={styles.headline}>{c.brand.headline}</p>
            <p className={styles.brandBody}>{c.brand.body}</p>
          </div>
        </div>
      </Main>
      <ToastRegion />
    </div>
  );
}

/*
 * Sign in. Tokens only; container breakpoints are the only literals (CSS can't read them from variables).
 * Narrow: a centred card. From 960px of the block's own width: form | brand panel, and the card loses its chrome.
 */

.root {
  --_gutter: var(--strata-space-4);

  container: sign-in / inline-size;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  min-block-size: 100%;
  background-color: var(--strata-color-surface-canvas);
  color: var(--strata-color-text-default);
  font-family: var(--strata-font-body);
  font-size: var(--strata-font-size-md);
  line-height: var(--strata-line-height-normal);
  text-align: start;
}

.root :where(*, *::before, *::after) {
  box-sizing: border-box;
}

.root :where(h1, h2, h3, h4, h5, h6, p, ul) {
  margin: 0;
}

@container sign-in (min-width: 640px) {
  .root > * {
    --_gutter: var(--strata-space-8);
  }
}

/* Email addresses read left to right even on right-to-left pages, still aligned to the field's start. */
.ltrValue:dir(rtl) input {
  direction: ltr;
  text-align: end;
}

.layout {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
}

@container sign-in (min-width: 960px) {
  .layout {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  }
}

/* ------------------------------------------------------------------ *
 * Form side
 * ------------------------------------------------------------------ */

.formSide {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--strata-space-6);
  padding-block: var(--strata-space-10);
  padding-inline: var(--_gutter);
}

.card.card {
  inline-size: 100%;
  max-inline-size: calc(var(--strata-space-16) * 6.5);
}

@container sign-in (min-width: 960px) {
  /* Beside the brand panel the page itself is the surface; the card chrome would be a box in a box. */
  .card.card {
    border-color: transparent;
    background-color: transparent;
    box-shadow: none;
  }

  .cardHeader .logoMark {
    display: none;
  }
}

.cardHeader.cardHeader {
  justify-items: center;
  text-align: center;
}

@container sign-in (min-width: 960px) {
  .cardHeader.cardHeader {
    justify-items: start;
    text-align: start;
  }
}

.logoMark {
  display: inline-grid;
  place-items: center;
  inline-size: var(--strata-space-10);
  block-size: var(--strata-space-10);
  margin-block-end: var(--strata-space-2);
  border-radius: var(--strata-radius-button);
  background-color: var(--strata-color-action-primary-bg);
  color: var(--strata-color-action-primary-fg);
  font-family: var(--strata-font-heading);
  font-size: var(--strata-font-size-lg);
  font-weight: var(--strata-font-weight-bold);
  line-height: 1;
}

.title.title {
  font-size: var(--strata-font-size-xl);
  letter-spacing: var(--strata-font-heading-tracking);
}

.form {
  display: flex;
  flex-direction: column;
}

.fields.fields {
  display: grid;
  gap: var(--strata-field-gap);
}

.reveal.reveal {
  inline-size: max(var(--strata-space-6), calc(var(--strata-control-height) - var(--strata-space-3)));
  block-size: max(var(--strata-space-6), calc(var(--strata-control-height) - var(--strata-space-3)));
  min-inline-size: 0;
  min-block-size: 0;
  margin-inline-end: calc(var(--strata-space-2) * -1);
  color: var(--strata-color-text-subtle);
}

.options {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--strata-space-2) var(--strata-space-4);
}

.small.small {
  font-size: var(--strata-font-size-sm);
}

.full.full {
  inline-size: 100%;
}

.cardFooter.cardFooter {
  justify-content: center;
  gap: var(--strata-space-1);
  font-size: var(--strata-font-size-sm);
}

.muted {
  color: var(--strata-color-text-subtle);
}

.legal {
  display: flex;
  justify-content: center;
}

.legalList {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--strata-space-1) var(--strata-space-4);
  padding: 0;
  list-style: none;
}

.legalLink.legalLink {
  color: var(--strata-color-text-subtle);
  font-size: var(--strata-font-size-xs);
}

.legalLink.legalLink[data-hovered] {
  color: var(--strata-color-text-default);
}

/* ------------------------------------------------------------------ *
 * Brand panel (wide containers only)
 * ------------------------------------------------------------------ */

.brandPanel {
  display: none;
}

@container sign-in (min-width: 960px) {
  .brandPanel {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    gap: var(--strata-space-12);
    padding: var(--strata-space-12);
    background-color: var(--strata-color-action-primary-bg);
    background-image: radial-gradient(
        circle at 100% 0%,
        color-mix(in oklab, var(--strata-color-action-primary-fg) 14%, transparent),
        transparent 55%
      ),
      radial-gradient(
        circle at 0% 100%,
        color-mix(in oklab, var(--strata-color-action-primary-fg) 8%, transparent),
        transparent 45%
      );
    color: var(--strata-color-action-primary-fg);
  }
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: var(--strata-space-3);
}

.brandMark {
  display: inline-grid;
  place-items: center;
  inline-size: var(--strata-space-10);
  block-size: var(--strata-space-10);
  border-radius: var(--strata-radius-button);
  background-color: var(--strata-color-action-primary-fg);
  color: var(--strata-color-action-primary-bg);
  font-family: var(--strata-font-heading);
  font-size: var(--strata-font-size-lg);
  font-weight: var(--strata-font-weight-bold);
  line-height: 1;
}

.brandName {
  font-family: var(--strata-font-heading);
  font-size: var(--strata-font-size-xl);
  font-weight: var(--strata-font-weight-semibold);
  letter-spacing: var(--strata-font-heading-tracking);
}

.brandCopy {
  display: grid;
  gap: var(--strata-space-4);
  max-inline-size: 28ch;
}

.headline {
  font-family: var(--strata-font-heading);
  font-size: var(--strata-font-size-3xl);
  font-weight: var(--strata-font-weight-semibold);
  letter-spacing: var(--strata-font-heading-tracking);
  line-height: var(--strata-line-height-tight);
  text-wrap: balance;
}

.brandBody {
  max-inline-size: 36ch;
  font-size: var(--strata-font-size-lg);
  line-height: var(--strata-line-height-normal);
  text-wrap: pretty;
}

/**
 * Content for the sign-in block. Replace this object to translate or rebrand it; the component never hard-codes
 * copy. The brand panel (wide containers only) uses the product name and `brand`.
 */

export interface SignInContent {
  /** BCP 47 locale. */
  locale: string;
  product: { name: string };
  signIn: {
    title: string;
    subtitle: string;
    email: { label: string; placeholder: string; errors: { required: string; invalid: string } };
    password: {
      label: string;
      /** Accessible names of the show/hide toggle. */
      show: string;
      hide: string;
      forgot: string;
      errors: { required: string };
    };
    remember: string;
    submit: string;
    /** Text of the divider between password and passkey sign-in. */
    or: string;
    passkey: string;
    signUp: { prompt: string; action: string };
    legal: { terms: string; privacy: string; help: string };
    brand: { headline: string; body: string };
    /** Toast after a successful (demo) sign-in. */
    success: { title: string };
  };
}

export const signInContent: SignInContent = {
  locale: 'en-US',
  product: { name: 'Acme' },
  signIn: {
    title: 'Sign in to Acme',
    subtitle: 'Welcome back. Enter your details to continue.',
    email: {
      label: 'Email',
      placeholder: 'you@example.com',
      errors: { required: 'Enter your email address', invalid: 'Enter an email address like name@example.com' },
    },
    password: {
      label: 'Password',
      show: 'Show password',
      hide: 'Hide password',
      forgot: 'Forgot password?',
      errors: { required: 'Enter your password' },
    },
    remember: 'Keep me signed in on this device',
    submit: 'Sign in',
    or: 'or',
    passkey: 'Continue with passkey',
    signUp: { prompt: 'New to Acme?', action: 'Create an account' },
    legal: { terms: 'Terms', privacy: 'Privacy', help: 'Help center' },
    brand: {
      headline: 'Your money, clearly.',
      body: 'Payments, savings goals and card controls in one place, with security built in.',
    },
    success: { title: 'You’re signed in' },
  },
};
